-- HELIOS (D11): additive gold shadow observation tables. No existing table, index or default is changed.
-- Generated by prisma migrate diff, filtered to the three new models, plus hand-written CHECK constraints.

CREATE TABLE "GoldShadowIngestRun" (
    "id" TEXT NOT NULL,
    "provider" TEXT NOT NULL,
    "environment" TEXT NOT NULL,
    "instrument" TEXT NOT NULL,
    "transport" TEXT NOT NULL,
    "configHash" TEXT NOT NULL,
    "qualityPolicyHash" TEXT NOT NULL,
    "samplingPolicyHash" TEXT NOT NULL,
    "leaseOwner" TEXT,
    "leaseExpiresAt" TIMESTAMPTZ(6),
    "status" TEXT NOT NULL DEFAULT 'RUNNING',
    "startedAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "heartbeatAt" TIMESTAMPTZ(6),
    "finishedAt" TIMESTAMPTZ(6),
    "polls" INTEGER NOT NULL DEFAULT 0,
    "accepted" INTEGER NOT NULL DEFAULT 0,
    "suppressed" INTEGER NOT NULL DEFAULT 0,
    "rejected" INTEGER NOT NULL DEFAULT 0,
    "providerFailures" INTEGER NOT NULL DEFAULT 0,
    "lastErrorCode" TEXT,
    "rejectionSamples" JSONB NOT NULL DEFAULT '[]',

    CONSTRAINT "GoldShadowIngestRun_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "GoldShadowQuote" (
    "id" TEXT NOT NULL,
    "runId" TEXT NOT NULL,
    "provider" TEXT NOT NULL,
    "environment" TEXT NOT NULL,
    "instrument" TEXT NOT NULL,
    "quoteKind" TEXT NOT NULL DEFAULT 'REFERENCE_MARKET_QUOTE',
    "providerTimeRaw" TEXT NOT NULL,
    "eventTime" TIMESTAMPTZ(6) NOT NULL,
    "receivedAt" TIMESTAMPTZ(6) NOT NULL,
    "eventIdentity" TEXT NOT NULL,
    "payloadHash" TEXT NOT NULL,
    "bid" DECIMAL(24,8) NOT NULL,
    "ask" DECIMAL(24,8) NOT NULL,
    "mid" DECIMAL(24,8) NOT NULL,
    "spread" DECIMAL(24,8) NOT NULL,
    "providerTradeable" BOOLEAN,
    "sessionState" TEXT NOT NULL,
    "qualityVerdict" TEXT NOT NULL,
    "qualityReasons" TEXT[],
    "qualityPolicyHash" TEXT NOT NULL,
    "samplingPolicyHash" TEXT NOT NULL,
    "bucketStart" TIMESTAMPTZ(6) NOT NULL,
    "executionEligible" BOOLEAN NOT NULL DEFAULT false,
    "createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "GoldShadowQuote_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "GoldShadowSamplingBucket" (
    "id" TEXT NOT NULL,
    "provider" TEXT NOT NULL,
    "environment" TEXT NOT NULL,
    "instrument" TEXT NOT NULL,
    "samplingPolicyHash" TEXT NOT NULL,
    "bucketStart" TIMESTAMPTZ(6) NOT NULL,
    "quoteId" TEXT NOT NULL,
    "firstReceivedAt" TIMESTAMPTZ(6) NOT NULL,
    "lastReceivedAt" TIMESTAMPTZ(6) NOT NULL,
    "suppressedCount" INTEGER NOT NULL DEFAULT 0,

    CONSTRAINT "GoldShadowSamplingBucket_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "GoldShadowIngestRun_instrument_startedAt_idx" ON "GoldShadowIngestRun"("instrument", "startedAt");

CREATE INDEX "GoldShadowIngestRun_status_leaseExpiresAt_idx" ON "GoldShadowIngestRun"("status", "leaseExpiresAt");

CREATE INDEX "GoldShadowQuote_instrument_eventTime_id_idx" ON "GoldShadowQuote"("instrument", "eventTime", "id");

CREATE INDEX "GoldShadowQuote_runId_receivedAt_idx" ON "GoldShadowQuote"("runId", "receivedAt");

CREATE UNIQUE INDEX "GoldShadowQuote_provider_environment_instrument_eventIdenti_key" ON "GoldShadowQuote"("provider", "environment", "instrument", "eventIdentity");

CREATE UNIQUE INDEX "GoldShadowQuote_provider_environment_instrument_samplingPol_key" ON "GoldShadowQuote"("provider", "environment", "instrument", "samplingPolicyHash", "bucketStart");

CREATE UNIQUE INDEX "GoldShadowSamplingBucket_quoteId_key" ON "GoldShadowSamplingBucket"("quoteId");

CREATE UNIQUE INDEX "GoldShadowSamplingBucket_provider_environment_instrument_sa_key" ON "GoldShadowSamplingBucket"("provider", "environment", "instrument", "samplingPolicyHash", "bucketStart");

ALTER TABLE "GoldShadowQuote" ADD CONSTRAINT "GoldShadowQuote_runId_fkey" FOREIGN KEY ("runId") REFERENCES "GoldShadowIngestRun"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

ALTER TABLE "GoldShadowSamplingBucket" ADD CONSTRAINT "GoldShadowSamplingBucket_quoteId_fkey" FOREIGN KEY ("quoteId") REFERENCES "GoldShadowQuote"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- Reference quotes are never executable, whatever the application sends.
ALTER TABLE "GoldShadowQuote" ADD CONSTRAINT "GoldShadowQuote_not_executable" CHECK ("executionEligible" = false);
ALTER TABLE "GoldShadowQuote" ADD CONSTRAINT "GoldShadowQuote_kind" CHECK ("quoteKind" = 'REFERENCE_MARKET_QUOTE');
-- Two-sided, uncrossed, positive prices; mid and spread consistent with bid and ask exactly.
ALTER TABLE "GoldShadowQuote" ADD CONSTRAINT "GoldShadowQuote_prices" CHECK ("bid" > 0 AND "ask" > "bid" AND "spread" = "ask" - "bid" AND "mid" * 2 = "bid" + "ask");
ALTER TABLE "GoldShadowQuote" ADD CONSTRAINT "GoldShadowQuote_verdict" CHECK ("qualityVerdict" IN ('ACCEPTED','FLAGGED'));
ALTER TABLE "GoldShadowQuote" ADD CONSTRAINT "GoldShadowQuote_session" CHECK ("sessionState" IN ('OPEN','CLOSED','UNKNOWN'));
ALTER TABLE "GoldShadowQuote" ADD CONSTRAINT "GoldShadowQuote_hashes" CHECK ("eventIdentity" ~ '^[0-9a-f]{64}$' AND "payloadHash" ~ '^[0-9a-f]{64}$' AND "qualityPolicyHash" ~ '^[0-9a-f]{64}$' AND "samplingPolicyHash" ~ '^[0-9a-f]{64}$');
ALTER TABLE "GoldShadowQuote" ADD CONSTRAINT "GoldShadowQuote_raw_time" CHECK (length("providerTimeRaw") BETWEEN 20 AND 40 AND "providerTimeRaw" ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9:.]+Z$');
-- A quote cannot be received before it happened beyond a small clock tolerance, and its bucket must contain it.
ALTER TABLE "GoldShadowQuote" ADD CONSTRAINT "GoldShadowQuote_times" CHECK ("eventTime" <= "receivedAt" + interval '1 second' AND "bucketStart" <= "eventTime");
ALTER TABLE "GoldShadowIngestRun" ADD CONSTRAINT "GoldShadowIngestRun_status" CHECK ("status" IN ('RUNNING','STOPPED','FAILED','BUDGET_EXHAUSTED'));
ALTER TABLE "GoldShadowIngestRun" ADD CONSTRAINT "GoldShadowIngestRun_counters" CHECK ("polls" >= 0 AND "accepted" >= 0 AND "suppressed" >= 0 AND "rejected" >= 0 AND "providerFailures" >= 0);
ALTER TABLE "GoldShadowIngestRun" ADD CONSTRAINT "GoldShadowIngestRun_rejection_samples_bounded" CHECK (jsonb_typeof("rejectionSamples") = 'array' AND jsonb_array_length("rejectionSamples") <= 50);
ALTER TABLE "GoldShadowSamplingBucket" ADD CONSTRAINT "GoldShadowSamplingBucket_counts" CHECK ("suppressedCount" >= 0 AND "lastReceivedAt" >= "firstReceivedAt");

-- Quotes are immutable evidence: no UPDATE or DELETE.
CREATE FUNCTION "gold_shadow_quote_immutable"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'GoldShadowQuote is append-only';
END;
$$;
CREATE TRIGGER "GoldShadowQuote_append_only" BEFORE UPDATE OR DELETE ON "GoldShadowQuote" FOR EACH ROW EXECUTE FUNCTION "gold_shadow_quote_immutable"();
CREATE TRIGGER "GoldShadowQuote_no_truncate" BEFORE TRUNCATE ON "GoldShadowQuote" FOR EACH STATEMENT EXECUTE FUNCTION "gold_shadow_quote_immutable"();
